head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil54200";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil54200.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "input_599", fn: function(){ return ((dma_cap1.get("fncWrtTpCd") ?? (() => { throw new Error("unresolved:" + "cap1.fncWrtTpCd"); })()) === '1'); } }, { id: "input_601", fn: function(){ return ((dma_cap1.get("fncWrtTpCd") ?? (() => { throw new Error("unresolved:" + "cap1.fncWrtTpCd"); })()) === '2'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + "/" + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId","corpUsrNm"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil54200' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_register();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name input_599_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input_599_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil54200.input_599_onclick' }); }
};

/**
 * @method
 * @name input_601_onclick
 * @description 「수정」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input_601_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil54200.input_601_onclick' }); }
};

/**
 * @method
 * @name input_602_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_602_onclick = function(e){
    try {
        fn_toList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil54200.input_602_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_register
 * @description register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/listInvstg/cap.do",
        ref: "dma_registerReq",
        target: "dlt_acntgBasCd=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    const frm = $c.util.getComponent('CapForm');
    if ($c.util.getComponent('dma_registerReq').get('fncWrtTpCd')=== '1') {
        $c.util.getComponent('dma_registerReq').set('fncWrtTpCd', '2');
        $c.util.getComponent('dma_registerReq').set('method', 'insertCap');
    } else {
        if ($c.util.getComponent('dma_registerReq').get('fncWrtTpCd')=== '2') {
            $c.util.getComponent('dma_registerReq').set('method', 'updateCap');
        }
    }
    frm.action = 'cap.do';
    await scwin.tx_fn_register();
};

/**
 * @method
 * @name setSelectBox
 * @description set Select Box 처리
 * @param {*} listBzSeq listBzSeq
 * @returns {void}
 * @hidden N
 */
scwin.setSelectBox = function (listBzSeq) {
    const date = new Date();
    let year = "";
    const month = "";
    document.write("<option value='0000'>--- 선택 ---</option>");
    switch (listBzSeq) {
        case 1:
        for (let i = 6; i > 0; i--) {
            year = date.getFullYear();
            let text = "";
            if ($c.util.getComponent('slc_acntclsYy').getValue() === year) {
                text = "selected";
            }
            document.write("<option value='" + year + "' " + text + ">" + year + "년</option>");
            date.setYear(date.getFullYear() - 1);
        }
        break;
        case 2:
        for (let i = 6; i > 0; i--) {
            year = date.getFullYear();
            text = "";
            if ($c.util.getComponent('slc_acntclsYy').getValue() === year) {
                text = "selected";
            }
            document.write("<option value='" + year + "' " + text + ">" + year + "년</option>");
            date.setYear(date.getFullYear() - 1);
        }
        break;
        case 3:
        for (let i = 6; i > 0; i--) {
            year = date.getFullYear();
            text = "";
            if ($c.util.getComponent('slc_acntclsYy').getValue() === year) {
                text = "selected";
            }
            document.write("<option value='" + year + "' " + text + ">" + year + "년</option>");
            date.setYear(date.getFullYear() - 1);
        }
        break;
        case 4:
        for (let i = 6; i > 0; i--) {
            year = date.getFullYear();
            text = "";
            if ($c.util.getComponent('slc_acntclsYy').getValue() === year) {
                text = "selected";
            }
            document.write("<option value='" + year + "' " + text + ">" + year + "년</option>");
            date.setYear(date.getFullYear() - 1);
        }
        break;
    }
};
